?>
<div class="wrap cod-crm-wrap"><h1>Reports & Analytics</h1>
<form method="get" class="cod-crm-filters"><input type="hidden" name="page" value="cod-crm-reports"><input type="date" name="date_from" value="<?php echo esc_attr($from); ?>"><input type="date" name="date_to" value="<?php echo esc_attr($to); ?>"><button class="button">Apply</button></form>
<div class="cod-crm-card"><h2>Daily Summary</h2><table class="widefat striped"><thead><tr><th>Date</th><th>Total</th><th>Confirmed</th><th>Cancelled</th><th>No Answer</th><th>Wrong No.</th><th>Not Picked</th><th>Switched Off</th><th>Busy</th><th>Callback</th><th>Prepaid</th><th>Rate %</th></tr></thead><tbody><?php foreach($data['daily'] as $r): $rate=$r['total']>0?round(($r['confirmed']/$r['total'])*100,2):0; ?><tr><td><?php echo esc_html($r['d']); ?></td><td><?php echo esc_html($r['total']); ?></td><td><?php echo esc_html($r['confirmed']); ?></td><td><?php echo esc_html($r['cancelled']); ?></td><td><?php echo esc_html($r['no_answer']); ?></td><td><?php echo esc_html($r['wrong_number']); ?></td><td><?php echo esc_html($r['not_picked']); ?></td><td><?php echo esc_html($r['switched_off']); ?></td><td><?php echo esc_html($r['busy']); ?></td><td><?php echo esc_html($r['callback_requested']); ?></td><td><?php echo esc_html($r['prepaid']); ?></td><td><?php echo esc_html((string)$rate); ?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="cod-crm-card"><h2>Agent Performance</h2><table class="widefat striped"><thead><tr><th>Agent</th><th>Total Calls</th><th>Confirmed</th><th>Cancelled</th><th>Avg Duration</th><th>Confirm Rate %</th><th>Pending Callbacks</th></tr></thead><tbody><?php foreach($data['agent'] as $r): $u=get_user_by('id',intval($r['agent_id'])); $rate=$r['total_calls']>0?round(($r['confirmed']/$r['total_calls'])*100,2):0; ?><tr><td><?php echo esc_html($u?$u->display_name:'System'); ?></td><td><?php echo esc_html($r['total_calls']); ?></td><td><?php echo esc_html($r['confirmed']); ?></td><td><?php echo esc_html($r['cancelled']); ?></td><td><?php echo esc_html(round((float)$r['avg_duration'],2)); ?></td><td><?php echo esc_html((string)$rate); ?></td><td><?php echo esc_html($r['pending_callbacks']); ?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="cod-crm-card"><h2>Outcome Distribution</h2><canvas id="codCrmPieChart" height="120"></canvas></div>
