<div class="cod-crm-card"><h2>RTO Risk Report</h2><table class="widefat striped"><thead><tr><th>Order ID</th><th>Customer</th><th>Phone</th><th>Attempts</th><th>Last Outcome</th><th>Last Called</th></tr></thead><tbody><?php foreach($data['rto'] as $r): ?><tr><td><?php echo esc_html($r['order_id']); ?></td><td><?php echo esc_html($r['customer_name']); ?></td><td><?php echo esc_html($r['customer_phone']); ?></td><td><?php echo esc_html($r['total_attempts']); ?></td><td><?php echo esc_html($r['last_outcome']); ?></td><td><?php echo esc_html($r['last_called']); ?></td></tr><?php endforeach; ?></tbody></table></div>
</div>
